          *(float *)((uint8_t *)&simdRegister + FloatDataSecondaryOffset) = processedFloatValue;
          statusFlags = movmskps(validationFlags, simdRegister);
          processedFloatValue = (float)(int32_t)(integerConversionValue - (statusFlags & 1));
